<style>body{font-family:sans-serif;margin:1em}.cols{display:flex;gap:1em;align-items:flex-start}.col{background:#eee;padding:.5em;min-width:220px;border-radius:4px}.card{background:#fff;margin:.4em 0;padding:.4em;border-radius:3px;box-shadow:0 1px 2px #888}</style></head>
<body><h1>Kanban</h1><div id="app"></div>
<script>
let token=localStorage.getItem('token'),boardId=null;
const app=document.getElementById('app');
async function api(m,p,b){const r=await fetch('/api'+p,{method:m,headers:{'content-type':'application/json',...(token?{authorization:'Bearer '+token}:{})},body:b?JSON.stringify(b):undefined});
 if(r.status===204)return null;const j=await r.json();if(!r.ok){alert(j.message||j.error);throw new Error(j.error)}return j}
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function login(){app.innerHTML='<h2>Login / Register</h2><input id=u placeholder=username><input id=p type=password placeholder=password><button id=li>Login</button><button id=re>Register</button>';
 const cred=()=>({username:u.value,password:p.value});
 li.onclick=async()=>{const r=await api('POST','/auth/login',cred());token=r.token;localStorage.setItem('token',token);boards()};
 re.onclick=async()=>{await api('POST','/auth/register',cred());li.click()}}
async function boards(){boardId=null;const l=await api('GET','/boards').catch(()=>null);if(!l){token=null;return login()}
 app.innerHTML='<button id=lo>Logout</button><h2>Boards</h2><ul>'+l.map(b=>'<li><a href="#" data-id="'+esc(b.id)+'">'+esc(b.name)+'</a> ('+esc(b.role)+')</li>').join('')+'</ul><input id=bn placeholder="new board"><button id=bc>Create board</button>';
 lo.onclick=async()=>{await api('POST','/auth/logout');token=null;localStorage.removeItem('token');login()};
 bc.onclick=async()=>{await api('POST','/boards',{name:bn.value});boards()};
 app.querySelectorAll('a').forEach(a=>a.onclick=e=>{e.preventDefault();board(a.dataset.id)})}
async function board(id){boardId=id;const b=await api('GET','/boards/'+id);
 app.innerHTML='<button id=bk>Back</button><h2>'+esc(b.name)+'</h2><div class=cols>'+b.columns.map(c=>'<div class=col data-id="'+esc(c.id)+'"><h3>'+esc(c.name)+(c.wipLimit?' ('+c.cards.length+'/'+c.wipLimit+')':'')+'</h3>'+
  c.cards.map(k=>'<div class=card draggable=true data-id="'+esc(k.id)+'">'+esc(k.title)+'<br>'+b.columns.filter(o=>o.id!==c.id).map(o=>'<button class=mv data-card="'+esc(k.id)+'" data-to="'+esc(o.id)+'">→ '+esc(o.name)+'</button>').join('')+'</div>').join('')+
  '<input class=nt placeholder="new card"><button class=ac data-col="'+esc(c.id)+'">Add card</button></div>').join('')+'</div>';
 bk.onclick=boards;
 app.querySelectorAll('.ac').forEach(x=>x.onclick=async()=>{await api('POST','/columns/'+x.dataset.col+'/cards',{title:x.previousSibling.value});board(id)});
 const mv=async(c,to)=>{await api('POST','/cards/'+c+'/move',{columnId:to});board(id)};
 app.querySelectorAll('.mv').forEach(x=>x.onclick=()=>mv(x.dataset.card,x.dataset.to));
 app.querySelectorAll('.card').forEach(x=>x.ondragstart=e=>e.dataTransfer.setData('text',x.dataset.id));
 app.querySelectorAll('.col').forEach(x=>{x.ondragover=e=>e.preventDefault();x.ondrop=e=>{e.preventDefault();mv(e.dataTransfer.getData('text'),x.dataset.id)}})}
token?boards():login();
</script></body></html>`;
EOF

