    let names = ['To Do', 'In Progress', 'Done'];
    if (columns !== undefined) {
      if (!Array.isArray(columns) || !columns.every((c) => isStr(c) && c.length >= 1 && c.length <= 100)) throw bad('invalid columns');
      names = columns;
    }
    const b = { id: uid(), name, description: description ?? '', ownerId: user.id, createdAt: now(), members: { [user.id]: 'owner' } };
    db.boards[b.id] = b;
    log(b.id, 'board.created', user.id, null, { name });
    names.forEach((n, i) => {
      const c = { id: uid(), boardId: b.id, name: n, position: i, wipLimit: null };
      db.columns[c.id] = c;
      log(b.id, 'column.created', user.id, null, { columnId: c.id, name: n });
    });
    save();
    return [201, boardView(b)];
  });
  route('GET', '/api/boards', true, ({ user }) =>
    [200, Object.values(db.boards).filter((b) => b.members[user.id]).map((b) => ({ id: b.id, name: b.name, role: b.members[user.id] }))]);
  route('GET', '/api/boards/:id', true, ({ params, user }) => {
    const b = getBoard(params.id); need(b, user); return [200, boardView(b)];
  });
  route('PATCH', '/api/boards/:id', true, ({ params, body, user }) => {
    const b = getBoard(params.id); need(b, user, 'owner');
    if (body.name !== undefined && (!isStr(body.name) || body.name.length < 1 || body.name.length > 100)) throw bad('name must be 1-100 chars');
    if (body.description !== undefined && !isStr(body.description)) throw bad('invalid description');
    if (body.name !== undefined) b.name = body.name;
    if (body.description !== undefined) b.description = body.description;
    save(); return [200, boardView(b)];
  });
  route('DELETE', '/api/boards/:id', true, ({ params, user }) => {
    const b = getBoard(params.id); need(b, user, 'owner');
    for (const k of ['columns', 'cards', 'labels']) for (const [id, x] of Object.entries(db[k])) if (x.boardId === b.id) delete db[k][id];
    for (const [id, c] of Object.entries(db.comments)) if (!db.cards[c.cardId]) delete db.comments[id];
    db.activity = db.activity.filter((a) => a.boardId !== b.id);
    delete db.boards[b.id]; save(); return [204];
  });
  route('POST', '/api/boards/:id/members', true, ({ params, body, user }) => {
    const b = getBoard(params.id); need(b, user, 'owner');
    if (!isStr(body.username)) throw bad('username required');
    if (body.role !== 'editor' && body.role !== 'viewer') throw bad('role must be editor or viewer');
    const t = Object.values(db.users).find((u) => u.username === body.username.toLowerCase());
    if (!t) throw notFound('user not found');
    if (b.members[t.id]) throw conflict('already a member');
    b.members[t.id] = body.role;
    log(b.id, 'member.added', user.id, null, { userId: t.id, role: body.role });
    save(); return [201, { userId: t.id, username: t.username, role: body.role }];
  });
  route('PATCH', '/api/boards/:id/members/:userId', true, ({ params, body, user }) => {
    const b = getBoard(params.id); need(b, user, 'owner');
    if (!b.members[params.userId]) throw notFound('member not found');
    if (body.role !== 'editor' && body.role !== 'viewer') throw bad('role must be editor or viewer');
    if (params.userId === b.ownerId) throw bad('cannot change the owner role');
    b.members[params.userId] = body.role; save();
    return [200, { userId: params.userId, username: db.users[params.userId]?.username, role: body.role }];
  });
  route('DELETE', '/api/boards/:id/members/:userId', true, ({ params, user }) => {
    const b = getBoard(params.id);
    if (params.userId !== user.id) need(b, user, 'owner'); else need(b, user);
    if (!b.members[params.userId]) throw notFound('member not found');
    if (params.userId === b.ownerId) throw bad('cannot remove the owner');
    delete b.members[params.userId];
    for (const c of Object.values(db.cards)) if (c.boardId === b.id) c.assignees = c.assignees.filter((a) => a !== params.userId);
    save(); return [204];
  });

  // columns
  route('POST', '/api/boards/:id/columns', true, ({ params, body, user }) => {
    const b = getBoard(params.id); need(b, user, 'editor');
    if (!isStr(body.name) || body.name.length < 1 || body.name.length > 100) throw bad('name must be 1-100 chars');
    const wip = body.wipLimit === undefined ? null : body.wipLimit; validWip(wip);
    const c = { id: uid(), boardId: b.id, name: body.name, position: boardCols(b.id).length, wipLimit: wip };
    db.columns[c.id] = c;
    log(b.id, 'column.created', user.id, null, { columnId: c.id, name: c.name });
    save(); return [201, { ...c, cards: [] }];
  });
  route('PATCH', '/api/columns/:id', true, ({ params, body, user }) => {
    const c = getCol(params.id); const b = getBoard(c.boardId); need(b, user, 'editor');
    if (body.name !== undefined && (!isStr(body.name) || body.name.length < 1 || body.name.length > 100)) throw bad('name must be 1-100 chars');
    if (body.wipLimit !== undefined) validWip(body.wipLimit);
    if (body.position !== undefined) checkPos(body.position);
    if (body.name !== undefined) c.name = body.name;
    if (body.wipLimit !== undefined) c.wipLimit = body.wipLimit;
    if (body.position !== undefined) {
      const list = boardCols(b.id).filter((x) => x.id !== c.id);
      list.splice(clampPos(body.position, list.length), 0, c); renum(list);
    }
    save(); return [200, { ...c, cards: colCards(c.id).map(cardView) }];
  });
  route('DELETE', '/api/columns/:id', true, ({ params, query, user }) => {
    const c = getCol(params.id); const b = getBoard(c.boardId); need(b, user, 'editor');
    const cards = colCards(c.id);
    if (cards.length && query.get('force') !== 'true') throw conflict('column has cards');
    for (const k of cards) { delete db.cards[k.id]; dropComments(k.id); }
    delete db.columns[c.id]; renum(boardCols(b.id)); save(); return [204];
  });
  const dropComments = (cardId) => { for (const [id, c] of Object.entries(db.comments)) if (c.cardId === cardId) delete db.comments[id]; };

  // cards
  route('POST', '/api/columns/:id/cards', true, ({ params, body, user }) => {
    const col = getCol(params.id); const b = getBoard(col.boardId); need(b, user, 'editor');
    validTitle(body.title);
    if (body.description !== undefined && body.description !== null && !isStr(body.description)) throw bad('invalid description');
    const assignees = body.assignees ?? [], labels = body.labels ?? [];
    checkAssLabels(b, assignees, labels);
    const due = body.dueDate ?? null;
    if (due !== null && !validDate(due)) throw bad('dueDate must be YYYY-MM-DD');
    if (body.position !== undefined) checkPos(body.position);
    checkWip(col);
    const t = now();
    const card = { id: uid(), boardId: b.id, columnId: col.id, title: body.title, description: body.description ?? '', position: 0,
      assignees: [...new Set(assignees)], labels: [...new Set(labels)], dueDate: due, createdBy: user.id, createdAt: t, updatedAt: t };
    db.cards[card.id] = card;
    const list = colCards(col.id).filter((x) => x.id !== card.id);
    list.splice(body.position === undefined ? list.length : clampPos(body.position, list.length), 0, card); renum(list);
    log(b.id, 'card.created', user.id, card.id, { title: card.title, columnId: col.id });
    save(); return [201, cardView(card)];
  });
  route('GET', '/api/cards/:id', true, ({ params, user }) => {
    const c = getCard(params.id); need(getBoard(c.boardId), user); return [200, cardView(c)];
  });
  route('PATCH', '/api/cards/:id', true, ({ params, body, user }) => {
    const c = getCard(params.id); const b = getBoard(c.boardId); need(b, user, 'editor');
    if (body.title !== undefined) validTitle(body.title);
    if (body.description !== undefined && !isStr(body.description)) throw bad('invalid description');
    if (body.dueDate !== undefined && body.dueDate !== null && !validDate(body.dueDate)) throw bad('dueDate must be YYYY-MM-DD');
    checkAssLabels(b, body.assignees ?? c.assignees, body.labels ?? c.labels);
    for (const k of ['title', 'description', 'dueDate']) if (body[k] !== undefined) c[k] = body[k];
    if (body.assignees) c.assignees = [...new Set(body.assignees)];
    if (body.labels) c.labels = [...new Set(body.labels)];
    c.updatedAt = now();
    log(b.id, 'card.updated', user.id, c.id, { fields: Object.keys(body) });
    save(); return [200, cardView(c)];
  });
  route('DELETE', '/api/cards/:id', true, ({ params, user }) => {
    const c = getCard(params.id); const b = getBoard(c.boardId); need(b, user, 'editor');
    delete db.cards[c.id]; dropComments(c.id); renum(colCards(c.columnId));
    log(b.id, 'card.deleted', user.id, c.id, { title: c.title, columnId: c.columnId });
    save(); return [204];
  });
  route('POST', '/api/cards/:id/move', true, ({ params, body, user }) => {
    const c = getCard(params.id); const b = getBoard(c.boardId); need(b, user, 'editor');
    if (!isStr(body.columnId)) throw bad('columnId required');
    const target = db.columns[body.columnId];
    if (!target) throw notFound('column not found');
    if (target.boardId !== b.id) throw bad('column is on a different board');
    if (body.position !== undefined) checkPos(body.position);
    const from = c.columnId;
    if (from !== target.id) checkWip(target);
    const src = colCards(from).filter((x) => x.id !== c.id);
    if (from !== target.id) renum(src);
    const dst = from === target.id ? src : colCards(target.id);
    dst.splice(body.position === undefined ? dst.length : clampPos(body.position, dst.length), 0, c);
    c.columnId = target.id; renum(dst); c.updatedAt = now();
    log(b.id, 'card.moved', user.id, c.id, { fromColumnId: from, toColumnId: target.id, position: c.position });
    save(); return [200, cardView(c)];
  });

  // labels
  route('POST', '/api/boards/:id/labels', true, ({ params, body, user }) => {
    const b = getBoard(params.id); need(b, user, 'editor');
    if (!isStr(body.name) || !body.name.length || body.name.length > 100) throw bad('invalid name');
    if (!isStr(body.color) || !/^#[0-9a-fA-F]{6}$/.test(body.color)) throw bad('color must be #rrggbb');
    if (Object.values(db.labels).some((l) => l.boardId === b.id && l.name.toLowerCase() === body.name.toLowerCase())) throw conflict('label exists');
    const l = { id: uid(), boardId: b.id, name: body.name, color: body.color };
    db.labels[l.id] = l; save(); return [201, l];
  });
  route('DELETE', '/api/labels/:id', true, ({ params, user }) => {
    const l = db.labels[params.id]; if (!l) throw notFound('label not found');
    need(getBoard(l.boardId), user, 'editor');
    delete db.labels[l.id];
    for (const c of Object.values(db.cards)) if (c.labels.includes(l.id)) c.labels = c.labels.filter((x) => x !== l.id);
    save(); return [204];
  });

  // comments
  route('POST', '/api/cards/:id/comments', true, ({ params, body, user }) => {
    const c = getCard(params.id); const b = getBoard(c.boardId); need(b, user, 'editor');
    if (!isStr(body.body) || body.body.length < 1 || body.body.length > 5000) throw bad('body must be 1-5000 chars');
    const m = { id: uid(), cardId: c.id, authorId: user.id, body: body.body, createdAt: now() };
    db.comments[m.id] = m;
    log(b.id, 'comment.added', user.id, c.id, { commentId: m.id });
    save(); return [201, m];
  });
  route('GET', '/api/cards/:id/comments', true, ({ params, user }) => {
    const c = getCard(params.id); need(getBoard(c.boardId), user);
    return [200, Object.values(db.comments).filter((m) => m.cardId === c.id)];
  });
  route('DELETE', '/api/comments/:id', true, ({ params, user }) => {
    const m = db.comments[params.id]; if (!m) throw notFound('comment not found');
    const b = getBoard(db.cards[m.cardId].boardId); need(b, user);
    if (m.authorId !== user.id && b.ownerId !== user.id) throw forbidden('only the author or board owner');
    delete db.comments[m.id]; save(); return [204];
  });

  // search & activity
  route('GET', '/api/boards/:id/cards', true, ({ params, query, user }) => {
    const b = getBoard(params.id); need(b, user);
    const q = query.get('q'), as = query.get('assignee'), lb = query.get('label'), col = query.get('column'), due = query.get('due_before');
    if (due !== null && !validDate(due)) throw bad('due_before must be YYYY-MM-DD');
    const cols = boardCols(b.id); const out = [];
    for (const c of cols) for (const k of colCards(c.id)) {
      if (q && !(k.title.toLowerCase().includes(q.toLowerCase()) || k.description.toLowerCase().includes(q.toLowerCase()))) continue;
      if (as && !k.assignees.includes(as)) continue;
      if (lb && !k.labels.includes(lb)) continue;
      if (col && k.columnId !== col) continue;
      if (due && !(k.dueDate && k.dueDate < due)) continue;
      out.push(cardView(k));
    }
    return [200, out];
  });
  route('GET', '/api/boards/:id/activity', true, ({ params, query, user }) => {
    const b = getBoard(params.id); need(b, user);
    let limit = 50;
    if (query.has('limit')) { limit = Number(query.get('limit')); if (!Number.isInteger(limit) || limit < 1) throw bad('invalid limit'); }
    return [200, db.activity.filter((a) => a.boardId === b.id).reverse().slice(0, limit)];
  });

  // ---------- dispatcher ----------
  const send = (res, status, body, type = 'application/json') => {
    if (status === 204) { res.writeHead(204); return res.end(); }
    const data = type === 'application/json' ? JSON.stringify(body) : body;
    res.writeHead(status, { 'content-type': type + '; charset=utf-8', 'content-length': Buffer.byteLength(data) });
    res.end(data);
  };
  const readBody = (req) => new Promise((resolve, reject) => {
    const chunks = []; let n = 0;
    req.on('data', (c) => { n += c.length; if (n > 1e6) { reject(new HttpError(413, 'too_large', 'body too large')); req.destroy(); } else chunks.push(c); });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });

  return http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url, 'http://x');
      const path = url.pathname.length > 1 ? url.pathname.replace(/\/+$/, '') : url.pathname;
      if (req.method === 'GET' && (path === '/' || path === '/index.html')) return send(res, 200, HTML, 'text/html');
      if (!path.startsWith('/api/')) throw notFound('route not found');
      let matched = null, params = {}, pathMatched = false;
      for (const r of routes) {
        const m = r.re.exec(path); if (!m) continue;
        pathMatched = true;
        if (r.method !== req.method) continue;
        matched = r; r.keys.forEach((k, i) => { params[k] = decodeURIComponent(m[i + 1]); }); break;
      }
      if (!matched) throw pathMatched ? new HttpError(405, 'method_not_allowed', 'method not allowed') : notFound('route not found');
      let user = null, token = null;
      if (matched.auth) {
        const h = req.headers.authorization || '';
        token = h.startsWith('Bearer ') ? h.slice(7).trim() : null;
        user = token && db.users[tokens.get(token)];
        if (!user) throw new HttpError(401, 'unauthorized', 'authentication required');
      }
      let body = {};
      if (req.method === 'POST' || req.method === 'PATCH' || req.method === 'PUT') {
        const raw = await readBody(req);
        if (raw.trim()) { try { body = JSON.parse(raw); } catch { throw bad('invalid JSON'); } }
        if (!isObj(body)) throw bad('body must be a JSON object');
      }
      const [status, out] = matched.fn({ params, body, query: url.searchParams, user, token });
      send(res, status, out);
    } catch (e) {
      if (e instanceof HttpError) return send(res, e.status, { error: e.error, message: e.message });
      console.error(e);
      send(res, 500, { error: 'internal', message: 'internal error' });
    }
  });
}
