import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from '../../src/server.js';
test('cards, wip, move, search', async () => {
  const srv = createServer(); await new Promise(r => srv.listen(0, r));
  const base = `http://127.0.0.1:${srv.address().port}`;
  const call = async (m, p, b, t) => { const r = await fetch(base + p, { method: m, headers: { 'content-type': 'application/json', ...(t ? { authorization: `Bearer ${t}` } : {}) }, body: b ? JSON.stringify(b) : undefined }); return [r.status, r.status === 204 ? null : await r.json()]; };
  await call('POST', '/api/auth/register', { username: 'Bob', password: 'password123' });
  const [, { token: t }] = await call('POST', '/api/auth/login', { username: 'bob', password: 'password123' });
  const [, b] = await call('POST', '/api/boards', { name: 'B' }, t);
  const [c1, c2] = b.columns;
  await call('PATCH', `/api/columns/${c2.id}`, { wipLimit: 1 }, t);
  const [s, k] = await call('POST', `/api/columns/${c1.id}/cards`, { title: 'Hello' }, t);
  assert.equal(s, 201);
  assert.equal((await call('POST', `/api/cards/${k.id}/move`, { columnId: c2.id }, t))[0], 200);
  const [, k2] = await call('POST', `/api/columns/${c1.id}/cards`, { title: 'Two' }, t);
  const [ws, we] = await call('POST', `/api/cards/${k2.id}/move`, { columnId: c2.id }, t);
  assert.equal(ws, 409); assert.equal(we.error, 'wip_limit');
  assert.equal((await call('GET', `/api/boards/${b.id}/cards?q=hel`, null, t))[1].length, 1);
  const [, act] = await call('GET', `/api/boards/${b.id}/activity`, null, t);
  assert.equal(act[0].type, 'card.moved');
  assert.equal((await call('GET', '/api/boards', null))[0], 401);
  srv.close();
});
